using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;
using Parcs.Agent.Runtime;

public class Out { public double lo { get; set; } public double hi { get; set; } public double mid { get; set; } public long count { get; set; } public double midpoint { get; set; } }

public class Bis : IAgentComputation
{
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        const long M = 16777216L;
        const long K = 5000000L;
        string mode = input.CustomData ?? "";
        double lo = 0.0, hi = 1.0;
        long c = 0;
        Out p = null;
        if (mode != "first")
        {
            var prev = input.GetPreviousOutputs();
            foreach (var s in prev)
            {
                if (s == null) continue;
                var o = JsonSerializer.Deserialize<Out>(s);
                c += o.count;
                p = o;
            }
            if (p == null) return Task.FromResult(AgentLayerResult.Error("no previous outputs"));
            lo = p.lo; hi = p.hi;
            if (c >= K) hi = p.mid; else lo = p.mid;
        }
        if (mode == "final")
        {
            double m = (lo + hi) / 2.0;
            return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new Out { lo = lo, hi = hi, mid = m, count = 0, midpoint = m })));
        }
        double mid = (lo + hi) / 2.0;
        long cnt = 0;
        int T = input.TotalWorkers;
        for (long i = input.WorkerIndex + 1; i <= M; i += T)
        {
            ulong z = (ulong)i * 0x9E3779B97F4A7C15UL;
            z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL;
            z = (z ^ (z >> 27)) * 0x94D049BB133111EBUL;
            z = z ^ (z >> 31);
            double v = (double)(z % 2147483647UL) / 2147483647.0;
            if (v <= mid) cnt++;
        }
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new Out { lo = lo, hi = hi, mid = mid, count = cnt, midpoint = 0 })));
    }
}

